    // allocates stack space for every if/case branch local when no optimizations
    // are enabled. https://github.com/apple/swift-protobuf/issues/1034 and
    // https://github.com/apple/swift-protobuf/issues/1182
    try { if let v = self._provider {
      try visitor.visitSingularStringField(value: v, fieldNumber: 1)
    } }()
    try { if let v = self._kind {
      try visitor.visitSingularEnumField(value: v, fieldNumber: 2)
    } }()
    try { if let v = self._message {
      try visitor.visitSingularStringField(value: v, fieldNumber: 3)
    } }()
    try { if let v = self._throttledUntil {
      try visitor.visitSingularMessageField(value: v, fieldNumber: 4)
    } }()
    try unknownFields.traverse(visitor: &visitor)
  }

  public static func ==(lhs: Mavio_Plugin_V1_SubtitleProviderFailure, rhs: Mavio_Plugin_V1_SubtitleProviderFailure) -> Bool {
    if lhs._provider != rhs._provider {return false}
    if lhs._kind != rhs._kind {return false}
    if lhs._message != rhs._message {return false}
    if lhs._throttledUntil != rhs._throttledUntil {return false}
    if lhs.unknownFields != rhs.unknownFields {return false}
    return true
  }
